comment on table public.workflow_transitions is
  'Authoritative append-only state history. UPDATE and DELETE rejected by trigger. seq gives a total per-instance order. authorization_id is the (unwired) seam for atlas_authorizations.';
comment on table public.workflow_evidence is
  'Append-only verification records. source distinguishes a check Omnira performed (automated) from one a human ran elsewhere and reported (attested).';

-- Workflow gate authorization — the database half of the gate (PR2).
-- Full commentary: apps/web/supabase/migrations/20260829_workflow_gate_authorization.sql
--
-- Layer split (locked): TypeScript owns the canonical derivation, including
-- whether the pinned target_version_hash still matches the hash recomputed from
-- the instance's definition, state and evidence. SQL owns a STRICT SUBSET that
-- needs no derivation, so the two can never contradict each other.

create or replace function public.workflow_append_transition(
  p_instance_id      uuid,
  p_from_state       text,
  p_to_state         text,
  p_reason           text,
  p_actor            text,
  p_evidence_ref     uuid default null,
  p_authorization_id uuid default null
) returns public.workflow_transitions
language plpgsql
security definer
set search_path to ''
as $$
declare
  i          public.workflow_instances;
  t          public.workflow_transitions;
  d_spec     jsonb;
  from_json  jsonb;
  terminal   boolean;
  gated      boolean;
  is_advance boolean;
  granted_n  int;
  closed_n   int;
  chain_n    int;
begin
  select * into i from public.workflow_instances where id = p_instance_id for update;
  if not found then
    raise exception 'workflow_append_transition: unknown instance %', p_instance_id
      using errcode = 'foreign_key_violation';
  end if;

  if i.status <> 'active' then
    raise exception 'workflow_append_transition: instance % is % and accepts no further transitions',
      p_instance_id, i.status
      using errcode = 'restrict_violation';
  end if;

  if p_from_state is null then
    raise exception 'workflow_append_transition: from_state is required (the opening transition belongs to workflow_instantiate)'
      using errcode = 'check_violation';
  end if;
  if i.current_state is distinct from p_from_state then
    raise exception 'workflow_append_transition: stale transition — instance % is in "%" not "%"',
      p_instance_id, i.current_state, p_from_state
      using errcode = 'serialization_failure';
  end if;

  select spec into d_spec from public.workflow_defs where id = i.def_id;
  if not exists (
    select 1 from jsonb_array_elements(d_spec -> 'states') s where s ->> 'id' = p_to_state
  ) then
    raise exception 'workflow_append_transition: state "%" is not declared by % v%',
      p_to_state, i.def_key, i.def_version
      using errcode = 'check_violation';
  end if;

  -- ── Gate check ─────────────────────────────────────────────────────────────
  select s into from_json
  from jsonb_array_elements(d_spec -> 'states') s
  where s ->> 'id' = p_from_state;

  gated      := coalesce((from_json -> 'human_gate' ->> 'required')::boolean, false);
  -- Only crossing a gate FORWARD needs authority; failing backwards is redoing
  -- your own work. Same rule as the TypeScript machine.
  is_advance := (from_json ->> 'next_state') is not distinct from p_to_state;

  if gated and is_advance then
    if p_authorization_id is null then
      raise exception 'workflow_append_transition: leaving "%" crosses a required human gate — an authorization is required',
        p_from_state
        using errcode = 'insufficient_privilege';
    end if;

    select
      count(*),
      count(*) filter (
        where a.event_type = 'granted'
          and a.expires_at is not null
          and a.expires_at > now()
          and a.target_type = 'workflow_gate'
          and a.target_id = p_instance_id::text || ':' || p_from_state
          and a.project_id = i.project_id
      ),
      count(*) filter (
        where a.event_type in ('denied', 'revoked', 'superseded', 'expired')
      )
    into chain_n, granted_n, closed_n
    from public.atlas_authorizations a
    where a.authorization_id = p_authorization_id;

    if chain_n = 0 then
      raise exception 'workflow_append_transition: authorization % does not exist', p_authorization_id
        using errcode = 'insufficient_privilege';
    end if;
    if closed_n > 0 then
      raise exception 'workflow_append_transition: authorization % was denied, revoked, superseded or expired',
        p_authorization_id
        using errcode = 'insufficient_privilege';
    end if;
    if granted_n = 0 then
      raise exception 'workflow_append_transition: authorization % carries no live grant for instance % state "%"',
        p_authorization_id, p_instance_id, p_from_state
        using errcode = 'insufficient_privilege';
    end if;
  end if;

  insert into public.workflow_transitions (
    instance_id, from_state, to_state, reason, actor, evidence_ref, authorization_id
  ) values (
    p_instance_id, p_from_state, p_to_state, p_reason, p_actor, p_evidence_ref, p_authorization_id
  ) returning * into t;

  select coalesce(
    (select (s -> 'next_state') = 'null'::jsonb or s -> 'next_state' is null
     from jsonb_array_elements(d_spec -> 'states') s where s ->> 'id' = p_to_state),
    false
  ) into terminal;

  update public.workflow_instances set
    current_state = p_to_state,
    status        = case when terminal then 'complete' else status end,
    closed_at     = case when terminal then now() else closed_at end
  where id = p_instance_id;

  return t;
end;
$$;
revoke all on function public.workflow_append_transition(uuid, text, text, text, text, uuid, uuid)
  from public, anon, authenticated;
grant execute on function public.workflow_append_transition(uuid, text, text, text, text, uuid, uuid)
  to service_role;

grant select on public.atlas_authorizations to service_role;

-- Workflow scheduled continuation (PR3).
-- Full commentary: apps/web/supabase/migrations/20260829_workflow_scheduled_continuation.sql
--
-- The claim MOVES THE WAKE FORWARD (a visibility timeout) rather than clearing
-- it: a crashed tick therefore retries instead of losing the wake, and there is
-- no lease and no reaper for long-lived instances.

alter table public.workflow_instances
  add column if not exists last_tick_at      timestamptz,
  add column if not exists last_tick_outcome text;

comment on column public.workflow_instances.wake_at is
  'When this instance next becomes eligible for evaluation. NULL = not scheduled. '
  'Future = sleeping. <= now() = due. A claim pushes it forward as a visibility '
  'timeout; a crashed tick therefore retries rather than losing the wake.';

drop index if exists public.workflow_instances_wake_idx;
create index if not exists workflow_instances_due_idx
  on public.workflow_instances (wake_at)
  where status = 'active' and wake_at is not null;

create or replace function public.workflow_schedule_wake(
  p_instance_id uuid, p_wake_at timestamptz, p_actor text, p_reason text
) returns public.workflow_instances
language plpgsql security definer set search_path to '' as $$
declare i public.workflow_instances; prev timestamptz;
begin
  select * into i from public.workflow_instances where id = p_instance_id for update;
  if not found then
    raise exception 'workflow_schedule_wake: unknown instance %', p_instance_id
      using errcode = 'foreign_key_violation';
  end if;
  if i.status <> 'active' then
    raise exception 'workflow_schedule_wake: instance % is % and cannot be scheduled',
      p_instance_id, i.status using errcode = 'restrict_violation';
  end if;
  if p_wake_at is null then
    raise exception 'workflow_schedule_wake: wake_at is required (use workflow_clear_wake to unschedule)'
      using errcode = 'check_violation';
  end if;

  prev := i.wake_at;
  update public.workflow_instances set wake_at = p_wake_at where id = p_instance_id returning * into i;

  insert into public.workflow_evidence (instance_id, state, check_key, result, source, detail)
  values (p_instance_id, i.current_state, 'scheduler.wake_scheduled', 'pass', 'automated',
          jsonb_build_object('wake_at', p_wake_at, 'previous_wake_at', prev,
                             'actor', p_actor, 'reason', p_reason));
  return i;
end;
$$;
revoke all on function public.workflow_schedule_wake(uuid, timestamptz, text, text)
  from public, anon, authenticated;
grant execute on function public.workflow_schedule_wake(uuid, timestamptz, text, text) to service_role;

create or replace function public.workflow_clear_wake(
  p_instance_id uuid, p_actor text, p_reason text
) returns public.workflow_instances
language plpgsql security definer set search_path to '' as $$
declare i public.workflow_instances; prev timestamptz;
begin
  select * into i from public.workflow_instances where id = p_instance_id for update;
  if not found then
    raise exception 'workflow_clear_wake: unknown instance %', p_instance_id
      using errcode = 'foreign_key_violation';
  end if;
  prev := i.wake_at;
  update public.workflow_instances set wake_at = null where id = p_instance_id returning * into i;
  if prev is not null then
    insert into public.workflow_evidence (instance_id, state, check_key, result, source, detail)
    values (p_instance_id, i.current_state, 'scheduler.wake_cleared', 'pass', 'automated',
            jsonb_build_object('previous_wake_at', prev, 'actor', p_actor, 'reason', p_reason));
  end if;
  return i;
end;
$$;
revoke all on function public.workflow_clear_wake(uuid, text, text) from public, anon, authenticated;
grant execute on function public.workflow_clear_wake(uuid, text, text) to service_role;

create or replace function public.workflow_claim_due(
  p_limit int default 20, p_visibility_seconds int default 300
) returns setof public.workflow_instances
language plpgsql security definer set search_path to '' as $$
begin
  return query
  update public.workflow_instances w set
    wake_at      = now() + make_interval(secs => p_visibility_seconds),
    last_tick_at = now()
  where w.id in (
    select d.id from public.workflow_instances d
    where d.status = 'active'
      and d.wake_at is not null
      and d.wake_at <= now()
      and not exists (
        select 1 from public.projects p
        where p.id = d.project_id and p.execution_paused = true
      )
    order by d.wake_at
    for update skip locked
    limit p_limit
  )
  returning w.*;
end;
$$;
revoke all on function public.workflow_claim_due(int, int) from public, anon, authenticated;
grant execute on function public.workflow_claim_due(int, int) to service_role;

create or replace function public.workflow_record_tick(
  p_instance_id uuid, p_outcome text,
  p_detail jsonb default '{}'::jsonb, p_next_wake_at timestamptz default null
) returns void
language plpgsql security definer set search_path to '' as $$
declare i public.workflow_instances; changed boolean;
begin
  select * into i from public.workflow_instances where id = p_instance_id for update;
  if not found then
    raise exception 'workflow_record_tick: unknown instance %', p_instance_id
      using errcode = 'foreign_key_violation';
  end if;

  changed := i.last_tick_outcome is distinct from p_outcome;

  update public.workflow_instances set
    last_tick_outcome = p_outcome, last_tick_at = now(), wake_at = p_next_wake_at
  where id = p_instance_id;

  if changed then
    insert into public.workflow_evidence (instance_id, state, check_key, result, source, detail)
    values (p_instance_id, i.current_state, 'scheduler.evaluation',
            case when p_outcome in ('failed', 'blocked') then 'fail' else 'pass' end,
            'automated',
            p_detail || jsonb_build_object('outcome', p_outcome,
                                           'previous_outcome', i.last_tick_outcome));
  end if;
end;
$$;
revoke all on function public.workflow_record_tick(uuid, text, jsonb, timestamptz)
  from public, anon, authenticated;
grant execute on function public.workflow_record_tick(uuid, text, jsonb, timestamptz) to service_role;

-- Guardian: the workflow tick joins the self-healing set. cron.schedule upserts
-- by name, so re-applying cannot create a duplicate job.
create or replace function omnira_cron.ensure_core_schedules()
returns text language plpgsql security definer set search_path to '' as $fn$
declare restored text := '';
begin
  if not exists (select 1 from cron.job where jobname = 'omnira_runs_drain') then
    perform cron.schedule('omnira_runs_drain', '* * * * *', 'select omnira_cron.call_vercel(''/api/runs/drain'')');
    restored := restored || 'omnira_runs_drain ';
  end if;
  if not exists (select 1 from cron.job where jobname = 'omnira_runs_reaper') then
    perform cron.schedule('omnira_runs_reaper', '* * * * *', 'select omnira_cron.reap_stuck_runs()');
    restored := restored || 'omnira_runs_reaper ';
  end if;
  if not exists (select 1 from cron.job where jobname = 'omnira_workflow_tick') then
    perform cron.schedule('omnira_workflow_tick', '* * * * *', 'select omnira_cron.call_vercel(''/api/workflows/tick'')');
    restored := restored || 'omnira_workflow_tick ';
  end if;
  return case when restored = '' then 'ok' else 'restored: ' || restored end;
end $fn$;

select omnira_cron.ensure_core_schedules();

-- PR9a — EXECUTION STOP-SAFETY.
-- See apps/web/supabase/migrations/20260830_execution_stop_safety.sql for the
-- full rationale. Summary: public.claim_runs ignored projects.execution_paused,
-- so pausing a project stopped the workflow scheduler but NOT the runs engine.
-- The stale 20260606_killswitch_cancel.sql must NEVER be replayed: its claim_runs
-- body predates fencing and would silently drop claim_id stamping. This is the
-- merge — pause filter from the kill switch, claim_id from fencing, nothing lost.

alter table public.runs add column if not exists cancel_reason text;
alter table public.runs add column if not exists cancelled_by  text;

create or replace function public.claim_runs(p_limit int, p_lease_seconds int default 280)
returns setof public.runs
language plpgsql security definer set search_path to '' as $$
begin
  return query
  update public.runs r set
    status      = 'running',
    claimed_at  = now(),
    started_at  = coalesce(r.started_at, now()),
    lease_until = now() + make_interval(secs => p_lease_seconds),
    attempts    = r.attempts + 1,
    claim_id    = gen_random_uuid()
  where r.id in (
    select ru.id from public.runs ru
    where ru.status = 'pending'
      and ru.attempts < ru.max_attempts
      and not exists (
        select 1 from public.projects p
        where p.id = ru.project_id and p.execution_paused = true
      )
    order by ru.created_at
    for update skip locked
    limit p_limit
  )
  returning r.*;
end $$;

revoke all on function public.claim_runs(int, int) from public, anon, authenticated;
grant execute on function public.claim_runs(int, int) to service_role;

create or replace function public.request_run_cancel(
  p_run_id uuid, p_project_id uuid, p_actor text default null, p_reason text default null
) returns int language plpgsql security definer set search_path to '' as $$
declare n int;
begin
  update public.runs set
    cancel_requested = true,
    cancel_reason    = coalesce(p_reason, cancel_reason),
    cancelled_by     = coalesce(p_actor,  cancelled_by)
  where id = p_run_id
    and project_id = p_project_id
    and status in ('pending', 'running');
  get diagnostics n = row_count;
  return n;
end $$;

